import os, socket, urllib.parse
print('PROXY_ENV=' + os.environ.get('HTTP_PROXY', 'unset') + ' ' + os.environ.get('HTTPS_PROXY', 'unset'))
print('NO_PROXY=' + os.environ.get('NO_PROXY', 'unset'))
def status(host, port):
    try:
        with socket.create_connection((host, port), timeout=10) as s:
            s.sendall(b'GET http://one.one.one.one/cdn-cgi/trace HTTP/1.1\r\nHost: one.one.one.one\r\nConnection: close\r\n\r\n')
            return s.recv(64).split(b' ')[1].decode()
    except (OSError, IndexError) as e:
        return 'ERROR ' + str(e)
proxy = urllib.parse.urlsplit(os.environ['HTTP_PROXY'])
print('VIA_PROXY=' + status(proxy.hostname, proxy.port))
print('BUILT_IN=' + status('10.231.1.254', 3128))
print('DIRECT=' + status('1.1.1.1', 80))
try:
    print('RESOLVED=' + socket.gethostbyname('example.com'))
except OSError as e:
    print('RESOLVED=ERROR', e)
EOF
